package org.apache.commons.codec.binary;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Test;

public class Base58Test_testObjectEncodeWithValidParameter {

    private static final Charset CHARSET_UTF8 = StandardCharsets.UTF_8;
    private static final String ORIGINAL_TEXT = "Hello World!";

    @Test
    void testObjectEncodeWithValidParameter() throws Exception {
        final Object originalBytes = ORIGINAL_TEXT.getBytes(CHARSET_UTF8);

        final Object encodedBytes = new Base58().encode(originalBytes);
        final byte[] decodedBytes = new Base58().decode((byte[]) encodedBytes);
        final String decodedText = new String(decodedBytes);

        assertEquals(ORIGINAL_TEXT, decodedText, "dest string does not equal original");
    }
}
